type RuntimeD1 = { prepare(sql: string): { run(): Promise<unknown> } };
type RuntimeEnv = { DB?: RuntimeD1 };
type Mode = "AUTOPILOT" | "EXCEPTIONS" | "MANUAL";
type StageStatus = "PASSED_REUSED" | "READY" | "TOURNAMENT_RUNNING" | "WORK_PACKET_READY" | "ARTIFACT_GENERATING" | "ARTIFACT_READY" | "MICRO_QA_RUNNING" | "REPAIR_REQUIRED" | "VERIFIED" | "FROZEN" | "HANDOFF_READY" | "INVALIDATED" | "AWAITING_APPROVAL" | "ESCALATED" | "BLOCKED";
type StageState = { key: string; order: number; status: StageStatus; score: number | null; attempt: number; evidence: string };
type Issue = { id: string; severity: "P0" | "P1" | "P2"; artifact: string; issue: string; evidence: string; rootCause: string; owner: string; acceptance: string; status: "OPEN" | "ROUTED" | "RESOLVED" | "ESCALATED"; stageKey: string };

type Contract = {
  key: string; order: number; label: string; objective: string; optimizeFor: string[]; inputs: string[]; deliverable: string;
  candidatePolicy: string; evaluators: string[]; hardGates: string[]; threshold: number; attemptLimit: number; invalidates: string[];
};

