let schemaReady: Promise<void> | null = null;
async function runtimeEnv() { const { env } = await import("cloudflare:workers"); return env as unknown as RuntimeEnv; }
async function ensureSchema() {
  if (!schemaReady) schemaReady = (async () => {
    const env = await runtimeEnv(); if (!env.DB) throw new Error("Production database is unavailable");
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS optimization_settings (project_id text PRIMARY KEY NOT NULL, mode text DEFAULT 'AUTOPILOT' NOT NULL, maximum_attempts integer DEFAULT 3 NOT NULL, minimum_improvement integer DEFAULT 3 NOT NULL, maximum_wave_stages integer DEFAULT 4 NOT NULL, regression_tolerance integer DEFAULT 5 NOT NULL, updated_at text DEFAULT CURRENT_TIMESTAMP NOT NULL)`).run();
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS optimization_cycles (id text PRIMARY KEY NOT NULL, project_id text NOT NULL, version integer NOT NULL, status text DEFAULT 'ACTIVE' NOT NULL, active_stage text NOT NULL, stage_state_json text NOT NULL, issue_ledger_json text NOT NULL, learning_json text NOT NULL, created_at text DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at text DEFAULT CURRENT_TIMESTAMP NOT NULL)`).run();
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS optimization_stage_runs (id text PRIMARY KEY NOT NULL, cycle_id text NOT NULL, project_id text NOT NULL, stage_key text NOT NULL, attempt integer DEFAULT 1 NOT NULL, status text NOT NULL, threshold integer NOT NULL, score integer DEFAULT 0 NOT NULL, contract_json text NOT NULL, candidates_json text NOT NULL, decision_json text NOT NULL, created_at text DEFAULT CURRENT_TIMESTAMP NOT NULL)`).run();
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS optimization_artifacts (id text PRIMARY KEY NOT NULL, cycle_id text NOT NULL, project_id text NOT NULL, stage_key text NOT NULL, version integer DEFAULT 1 NOT NULL, status text DEFAULT 'ARTIFACT_READY' NOT NULL, artifact_type text NOT NULL, title text NOT NULL, content_json text NOT NULL, source_run_id text NOT NULL, word_count integer DEFAULT 0 NOT NULL, created_at text DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at text DEFAULT CURRENT_TIMESTAMP NOT NULL)`).run();
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS optimization_artifact_qa (id text PRIMARY KEY NOT NULL, artifact_id text NOT NULL, cycle_id text NOT NULL, project_id text NOT NULL, stage_key text NOT NULL, attempt integer DEFAULT 1 NOT NULL, status text NOT NULL, decision text NOT NULL, score integer DEFAULT 0 NOT NULL, threshold integer NOT NULL, rubric_json text NOT NULL, issues_json text NOT NULL, regression_json text NOT NULL, created_at text DEFAULT CURRENT_TIMESTAMP NOT NULL)`).run();
  })().catch((error) => { schemaReady = null; throw error; }); await schemaReady;
}

function initialStages(): StageState[] { return contracts.map((contract) => ({ key: contract.key, order: contract.order, status: contract.order <= 3 ? "PASSED_REUSED" : contract.order === 4 ? "READY" : "INVALIDATED", score: contract.order <= 3 ? [88, 87, 86][contract.order - 1] : null, attempt: 0, evidence: contract.order <= 3 ? "Reused from the approved channel, audience and topic foundation; downstream execution invalidated by Quality Gate v2." : contract.order === 4 ? "First stage requiring a new optimized artifact." : "Blocked until upstream handoff passes." })); }
function initialIssues(): Issue[] { return [
  { id: "CQ-001", severity: "P0", artifact: "Script", issue: "Runtime and content depth are below mini-documentary quality.", evidence: "Current master is approximately 67 seconds; target is 7–10 minutes with 950+ words.", rootCause: "The initial MVP optimized for complete assembly rather than competitive depth.", owner: "Content architect", acceptance: "Locked 950–1,300 word script with a 3-act arc and verified claims.", status: "OPEN", stageKey: "SCRIPT" },
  { id: "CQ-002", severity: "P0", artifact: "Visual system", issue: "Visual fidelity and diversity are below competitor parity.", evidence: "Current master is 720p with a small set of visual units and families.", rootCause: "Storyboard used one scene per narration segment instead of a visual-beat system.", owner: "Visual director", acceptance: "1080p system, 35–45 visual beats, five visual families and no static state above seven seconds.", status: "OPEN", stageKey: "VISUAL_LANGUAGE" },
  { id: "CQ-003", severity: "P0", artifact: "Soundscape", issue: "Narration exists, but music, ambience and SFX are not designed.", evidence: "No complete background music and SFX inventory is detected.", rootCause: "Voice production was treated as the entire audio layer.", owner: "Sound director", acceptance: "Licensed music bed, ambience, transition SFX, emphasis hits and measured mix targets.", status: "OPEN", stageKey: "VOICE_SOUND" },
  { id: "CQ-004", severity: "P1", artifact: "Competitive intelligence", issue: "Reference analysis covers metadata and patterns, not scene-level production parity.", evidence: "No duration, visual-density or sound-design parity matrix is stored.", rootCause: "Reference Intelligence was introduced after the first master was complete.", owner: "Competitive analyst", acceptance: "Five-reference parity matrix linked to stage thresholds.", status: "OPEN", stageKey: "CREATIVE_STRATEGY" },
  { id: "CQ-005", severity: "P1", artifact: "Packaging", issue: "Current title is accurate but generic.", evidence: "Reference benchmark returned PACKAGE_ONLY before the stricter production review.", rootCause: "Packaging was optimized before the master met competitive quality.", owner: "Packaging strategist", acceptance: "Three promise-aligned test variants generated after final master approval.", status: "OPEN", stageKey: "PACKAGING" },
]; }
function genericCandidates(contract: Contract) { return [
  { label: `${contract.label} · champion`, thesis: `High-rigor ${contract.deliverable.toLowerCase()} optimized for ${contract.optimizeFor.slice(0, 3).join(", ")}.`, scores: Object.fromEntries(contract.optimizeFor.slice(0, 4).map((item, index) => [item, 91 - index])), risks: ["Requires downstream verification"] },
  { label: `${contract.label} · challenger`, thesis: `Alternative execution emphasizing ${contract.optimizeFor.slice().reverse().slice(0, 3).join(", ")}.`, scores: Object.fromEntries(contract.optimizeFor.slice(0, 4).map((item, index) => [item, 87 - index])), risks: ["May trade clarity for novelty"] },
  { label: `${contract.label} · baseline`, thesis: "Continue the current MVP approach with minimal changes.", scores: Object.fromEntries(contract.optimizeFor.slice(0, 4).map((item, index) => [item, 68 - index])), risks: ["Below competitive target"] },
]; }
function scoreCandidate(candidate: { scores: Record<string, number> }) { const values = Object.values(candidate.scores); return Math.round(values.reduce((sum, value) => sum + value, 0) / Math.max(1, values.length)); }

async function startCycle(projectId: string) {
  const db = await getDb(); const prior = await db.select().from(optimizationCycles).where(eq(optimizationCycles.projectId, projectId)).orderBy(desc(optimizationCycles.version)); const version = (prior[0]?.version || 0) + 1; const id = `${projectId}-OPT-V${version}`;
  await db.insert(optimizationCycles).values({ id, projectId, version, status: "ACTIVE", activeStage: "CREATIVE_STRATEGY", stageStateJson: JSON.stringify(initialStages()), issueLedgerJson: JSON.stringify(initialIssues()), learningJson: JSON.stringify({ qualityPrinciple: "Quality is designed into every artifact; final QA only verifies the system.", source: "Universal Quality Gate v2", calibrationStatus: "PILOT" }) });
  await db.update(videoProjects).set({ nextAction: "Run Creative Strategy candidate tournament", updatedAt: new Date().toISOString() }).where(eq(videoProjects.id, projectId));
  await db.insert(workflowEvents).values({ projectId, toStatus: "OPTIMIZED_REBUILD", eventType: "OPTIMIZATION_CYCLE_STARTED", summary: `Continuous Quality cycle v${version} started; downstream work invalidated from Creative Strategy` });
  return { id, version };
}

async function executeStage(projectId: string, cycleId: string) {
  const db = await getDb(); const [cycle] = await db.select().from(optimizationCycles).where(eq(optimizationCycles.id, cycleId)).limit(1); if (!cycle || cycle.projectId !== projectId) throw new Error("Optimization cycle not found");
  const contract = contracts.find((item) => item.key === cycle.activeStage); if (!contract) throw new Error("Active stage contract not found");
  const settingsRows = await db.select().from(optimizationSettings).where(eq(optimizationSettings.projectId, projectId)).limit(1); const settings = settingsRows[0];
  const priorRuns = await db.select().from(optimizationStageRuns).where(eq(optimizationStageRuns.cycleId, cycle.id)).orderBy(desc(optimizationStageRuns.createdAt)); const stageRuns = priorRuns.filter((run) => run.stageKey === contract.key); const attempt = stageRuns.length + 1;
  if (attempt > Math.min(contract.attemptLimit, settings.maximumAttempts)) return { stopped: true, reason: "ATTEMPT_BUDGET_EXHAUSTED", stage: contract.key };
  const rawCandidates = candidateLibrary[contract.key] || genericCandidates(contract); const candidates = rawCandidates.map((candidate, index) => ({ ...candidate, id: `${cycle.id}-${contract.key}-C${index + 1}`, compositeScore: scoreCandidate(candidate), status: "CHALLENGER" })).sort((a, b) => b.compositeScore - a.compositeScore); candidates[0].status = "CHAMPION";
  const winner = candidates[0]; const previousScore = stageRuns[0]?.score || 0; const improvement = previousScore ? winner.compositeScore - previousScore : winner.compositeScore; const noProgress = attempt > 1 && improvement < settings.minimumImprovement;
  const passed = winner.compositeScore >= contract.threshold && !noProgress; const runStatus = noProgress || attempt >= contract.attemptLimit && !passed ? "ESCALATED" : passed && settings.mode === "MANUAL" ? "AWAITING_APPROVAL" : passed ? "WORK_PACKET_READY" : "REPAIR_REQUIRED";
  const decision = { winnerId: winner.id, winnerLabel: winner.label, score: winner.compositeScore, threshold: contract.threshold, improvement, noProgress, outputType: "CONTROLLED_WORK_PACKET", rationale: passed ? "Champion cleared the stage contract and may be handed to the artifact worker." : noProgress ? "Improvement fell below the minimum delta; autonomous retries stopped." : "Champion did not clear the stage threshold." };
  await db.insert(optimizationStageRuns).values({ id: `${cycle.id}-${contract.key}-A${attempt}`, cycleId: cycle.id, projectId, stageKey: contract.key, attempt, status: runStatus, threshold: contract.threshold, score: winner.compositeScore, contractJson: JSON.stringify(contract), candidatesJson: JSON.stringify(candidates), decisionJson: JSON.stringify(decision) });
  const states = JSON.parse(cycle.stageStateJson) as StageState[]; const current = states.find((state) => state.key === contract.key); if (current) { current.status = runStatus as StageStatus; current.score = winner.compositeScore; current.attempt = attempt; current.evidence = decision.rationale; }
  const issues = JSON.parse(cycle.issueLedgerJson) as Issue[]; issues.filter((issue) => issue.stageKey === contract.key && issue.status === "OPEN").forEach((issue) => { issue.status = passed ? "ROUTED" : runStatus === "ESCALATED" ? "ESCALATED" : "OPEN"; });
  const nextStage = cycle.activeStage; let cycleStatus = cycle.status;
  if (runStatus === "ESCALATED") cycleStatus = "ESCALATED";
  await db.update(optimizationCycles).set({ status: cycleStatus, activeStage: nextStage, stageStateJson: JSON.stringify(states), issueLedgerJson: JSON.stringify(issues), updatedAt: new Date().toISOString() }).where(eq(optimizationCycles.id, cycle.id));
  await db.update(videoProjects).set({ nextAction: passed ? `Materialize and verify the ${contract.label} artifact` : runStatus === "ESCALATED" ? `Resolve escalated ${contract.label} decision` : `Repair ${contract.label} candidates`, updatedAt: new Date().toISOString() }).where(eq(videoProjects.id, projectId));
  await db.insert(workflowEvents).values({ projectId, toStatus: runStatus, eventType: "OPTIMIZATION_STAGE_COMPLETED", summary: `${contract.label} attempt ${attempt}: ${winner.label} scored ${winner.compositeScore}/${contract.threshold}; ${runStatus}` });
  return { stopped: false, stage: contract.key, stageLabel: contract.label, status: runStatus, score: winner.compositeScore, threshold: contract.threshold, winner: winner.label, nextStage };
}

async function approveHandoff(projectId: string) {
  const db = await getDb(); const [cycle] = await db.select().from(optimizationCycles).where(eq(optimizationCycles.projectId, projectId)).orderBy(desc(optimizationCycles.version)).limit(1); if (!cycle) throw new Error("Optimization cycle not found");
  const [latestRun] = await db.select().from(optimizationStageRuns).where(eq(optimizationStageRuns.cycleId, cycle.id)).orderBy(desc(optimizationStageRuns.createdAt)).limit(1); if (!latestRun || latestRun.stageKey !== cycle.activeStage || latestRun.status !== "AWAITING_APPROVAL") throw new Error("No stage handoff is awaiting approval");
  const contract = contracts.find((item) => item.key === cycle.activeStage); if (!contract) throw new Error("Stage contract not found"); const states = JSON.parse(cycle.stageStateJson) as StageState[]; const current = states.find((state) => state.key === contract.key); if (current) { current.status = "WORK_PACKET_READY"; current.evidence = "Human approved the champion work packet. Artifact generation is now authorized; downstream remains locked."; }
  await db.update(optimizationCycles).set({ stageStateJson: JSON.stringify(states), updatedAt: new Date().toISOString() }).where(eq(optimizationCycles.id, cycle.id)); await db.insert(workflowEvents).values({ projectId, toStatus: "WORK_PACKET_READY", eventType: "OPTIMIZATION_WORK_PACKET_APPROVED", summary: `${contract.label} champion approved for artifact generation; downstream remains locked` }); return { stage: contract.key, nextStage: contract.key };
}

const artifactStages = new Set(["CREATIVE_STRATEGY", "RESEARCH", "OUTLINE", "SCRIPT", "VISUAL_LANGUAGE", "STORYBOARD", "ASSET_TOURNAMENT"]);
function buildScriptSections(projectId: string) {
  const claimId = (number: number) => `${projectId}-DEPTH-CLM-${String(number).padStart(2, "0")}`;
  return [
    { time: "0:00–0:20", beat: "APPROVED is not paid", purposeCode: "HOOK_PARADOX", claimIds: [claimId(1), claimId(2)], text: "You tap your card. The terminal flashes APPROVED. The cashier moves on. It feels like your money just crossed the counter. It did not. That green word is permission—not payment—and the most important part of the transaction is still ahead." },
    { time: "0:20–0:50", beat: "The $100 case", purposeCode: "OPEN_LOOP_OBJECT", claimIds: [claimId(8), claimId(9)], text: "To expose what the screen hides, follow one illustrative one-hundred-dollar purchase. Keep that receipt in view, because its single number will soon mean several different things. The customer sees a charge. The merchant expects proceeds. Other participants calculate obligations and costs. But at this moment, none of those views is the merchant's settled cash. So where does the one hundred dollars go—and when does it become real money for the seller?" },
    { time: "0:50–1:30", beat: "Authorization request", purposeCode: "AUTH_ROUTE", claimIds: [claimId(3), claimId(12)], text: "First comes authorization: the fast question asked at checkout. The terminal sends a request into the merchant's acquiring side. Technical providers may help format and route it. A card network directs the message toward the bank that issued the card. The precise organizations and route vary, so do not picture one universal chain of six companies. Picture functional roles. One side accepts the sale, one routes the request, one applies network rules, and the issuer decides. Then the answer travels back through the system until APPROVED appears at the terminal. A round trip has happened. A final transfer has not." },
    { time: "1:30–2:10", beat: "Issuer decision", purposeCode: "AUTH_MEANING", claimIds: [claimId(1), claimId(3), claimId(5)], text: "What did the issuer actually decide? It checked whether the account could support the request under the information and risk controls available at that moment. An approval lets the merchant proceed. It may also create a hold or reduce the customer's available credit. But it does not guarantee that the merchant will ultimately be paid. The transaction may still need capture or submission, and an unused authorization may later expire or be released. This is the first mental shift: APPROVED is not a receipt for moved money. It is a temporary, conditional promise that the next steps may continue." },
    { time: "2:10–2:55", beat: "Functional cast", purposeCode: "ROLE_MODEL", claimIds: [claimId(3), claimId(12)], text: "Now widen the frame, but only enough to see the jobs. The merchant wants a valid sale. The acquiring side presents and processes the merchant's transactions. The network provides routing and operating rules. The issuer manages the customer's account and makes the authorization decision. Gateways and processors can supply technical connections along the path. In practice, one company may perform several roles, and different transactions may take different routes. That is why counting logos can mislead. The stable idea is functional: separate roles coordinate a decision, exchange records, calculate obligations, and fund them. No single APPROVED screen tells that whole story." },
    { time: "2:55–3:40", beat: "Why speed is not finality", purposeCode: "SEPARATION_LOGIC", claimIds: [claimId(2), claimId(4), claimId(5)], text: "Why design such a split system? Because checkout speed and financial finality solve different problems. Authorization must answer quickly enough to keep the line moving. Later processing needs a more complete record of what should actually be charged. A restaurant may add a tip. A hotel may authorize an estimate and submit a different final amount where the rules allow it. A merchant may close completed transactions in a later batch. Separating the quick permission from later accounting preserves a fast customer experience without pretending that every detail is final. The delay is not simply dead time. It is where a tentative checkout decision becomes a controlled financial record." },
    { time: "3:40–4:30", beat: "The receipt starts splitting", purposeCode: "MIDPOINT_REHOOK", claimIds: [claimId(6), claimId(8), claimId(9)], text: "Return to the receipt. Until now, one hundred dollars looked like one object moving through a pipe. That picture breaks here. The customer's purchase amount, the issuer's authorized exposure, the merchant's expected receivable, and the merchant's eventual proceeds are related—but they are not identical states. Costs also depend on card, merchant, transaction method, provider, and contract. There is no honest universal percentage that can describe every sale. Any waterfall shown here is therefore illustrative. The deeper reveal is not a particular fee. It is that one familiar number has split into several economic views, each owned by a different role and available at a different time." },
    { time: "4:30–5:20", beat: "Clearing", purposeCode: "CLEARING_MODEL", claimIds: [claimId(2), claimId(6)], text: "The next stage is clearing. After completed transactions are submitted, records and financial instructions are exchanged so the participants can calculate their obligations. Think of authorization as asking, may this purchase proceed? Clearing asks a different question: given the completed record, who now owes what? Transactions may be grouped, checked, reconciled, and translated into amounts due between participating institutions. The money has not simply leapt from the customer's card into the merchant's account. First, the system has to agree on the record and the obligations created by it. This hidden ledger is what turns a collection of checkout promises into something the institutions can fund." },
    { time: "5:20–6:05", beat: "Settlement", purposeCode: "SETTLEMENT_MODEL", claimIds: [claimId(7), claimId(8)], text: "Settlement follows that calculation. This is where the obligations determined through processing are funded between institutions. It is distinct from the earlier authorization response, and it is also useful to distinguish institutional settlement from the merchant's own payout. Those events are connected, but they need not be the same moment. The merchant's provider still has to make proceeds available under its operating arrangement. So the story has moved through three different verbs: authorize the purchase, clear the records, settle the obligations. Compressing all three into the word paid is why the terminal creates such a convincing illusion." },
    { time: "6:05–6:50", beat: "Merchant payout timing", purposeCode: "MERCHANT_PROCEEDS", claimIds: [claimId(8), claimId(10)], text: "Now the original one-hundred-dollar question can be answered. The merchant eventually receives proceeds according to its provider and contract, potentially adjusted for applicable charges, credits, rejections, or withholdings. Availability and bank-deposit timing vary by market, provider, risk profile, and operating arrangement. That is why this video cannot promise one universal deadline or one fixed net amount. What it can show is the structure. The receipt records the customer's purchase amount. The merchant's reporting may show an expected receivable. The payout reflects the applicable arrangement. Strong sales, pending card volume, and available bank cash can therefore describe different states of the same business day." },
    { time: "6:50–7:35", beat: "After the deposit", purposeCode: "POST_PAYMENT_RISK", claimIds: [claimId(11)], text: "Even a deposit is not the absolute end of every card story. A refund can send value back to the customer. A dispute can reopen the question of whether the transaction should stand. A chargeback or later adjustment can change the merchant's economics after the earlier approval and processing events. This does not mean card payments are unreliable. It means their reliability comes from rules for handling uncertainty, not from pretending uncertainty vanished at checkout. Each stage makes the commitment firmer, but later events can still matter. The system is better understood as a sequence of governed promises than as one irreversible instant transfer." },
    { time: "7:35–8:00", beat: "Approval redefined", purposeCode: "PAYOFF_SERIES_BRIDGE", claimIds: [claimId(1), claimId(7)], text: "Look again at the terminal. APPROVED no longer means the money arrived. It means the first coordinated decision succeeded and the purchase may proceed. Records still have to clear. Obligations still have to settle. Merchant proceeds follow their own arrangement. That tiny green word feels final because the infrastructure hides everything that follows. The next time a payment interface gives you one simple answer, ask what promise the hidden system has actually made. Cards are only the beginning." },
  ].map((section) => ({ ...section, factual: true, spokenWords: wordCount(section.text) }));
}

function wordCount(value: string) { return value.trim().split(/\s+/).filter(Boolean).length; }
function creativeArtifact() { return { summary: "A binding creative contract for a 7–10 minute faceless mini-documentary.", fields: [
  { label: "Primary viewer", value: "Curious US adults who use cards daily but do not understand the infrastructure beneath a two-second approval." },
  { label: "Transformation", value: "From 'approved means money moved' to a clear mental model of authorization, clearing, settlement, and merchant net proceeds." },
  { label: "Central question", value: "What actually happens after a card terminal says APPROVED?" },
  { label: "Champion angle", value: "Approval is not payment." },
  { label: "Thesis", value: "A card payment is a sequence of increasingly firm promises coordinated by separate roles—not a single instant transfer." },
  { label: "Story engine", value: "Follow one illustrative $100 purchase through a hidden network; change the meaning of APPROVED at every act." },
  { label: "Emotional arc", value: "Familiarity → contradiction → expanding invisible network → economic reveal → durable mental model." },
  { label: "Stakes", value: "The viewer discovers why the customer charge, the merchant deposit, fees, timing, and reversibility are not the same event." },
  { label: "Payoff", value: "APPROVED is permission and a temporary promise; settlement is the later movement of calculated obligations." },
  { label: "Visual engine", value: "Macro terminal footage + living transaction map + $100 receipt counter + timing lanes + illustrative fee waterfall." },
  { label: "Runtime contract", value: "7–10 minutes; 950–1,300 spoken words; no static visual state longer than seven seconds." },
  { label: "Originality guard", value: "Learn structural patterns from references, but reuse no distinctive wording, scene sequence, thumbnail composition, or unsupported figures." },
]}; }

